const styles=new CSSStyleSheet;styles.replaceSync("/*\n * Copyright 2018 The Chromium Authors. All rights reserved.\n * Use of this source code is governed by a BSD-style license that can be\n * found in the LICENSE file.\n */\n\n#console-prompt .CodeMirror {\n  padding: 3px 0 1px;\n}\n\n#console-prompt .CodeMirror-line {\n  padding-top: 0;\n}\n\n#console-prompt .CodeMirror-lines {\n  padding-top: 0;\n}\n\n#console-prompt .console-prompt-icon {\n  position: absolute;\n  left: -13px;\n  top: 2px;\n  user-select: none;\n}\n\n.console-eager-preview {\n  padding-bottom: 2px;\n  opacity: 60%;\n  position: relative;\n  height: 15px;\n}\n\n.console-eager-inner-preview {\n  text-overflow: ellipsis;\n  overflow: hidden;\n  margin-left: 4px;\n  height: 100%;\n  white-space: nowrap;\n}\n\n.preview-result-icon {\n  position: absolute;\n  left: -13px;\n  top: -1px;\n}\n\n.console-eager-inner-preview:empty,\n.console-eager-inner-preview:empty + .preview-result-icon {\n  opacity: 0%;\n}\n\n.console-prompt-icon.console-prompt-incomplete {\n  opacity: 65%;\n}\n\n/*# sourceURL=consolePrompt.css */\n");export default styles;